import type { ScaleName } from '@gblp/music-theory';
import type { CagedShape } from './components/soloin-fretboard/caged';

export interface LocalizedText {
  en: string;
  es: string;
}

export interface RiffNote {
  stringIndex: number; // 0 = high e ... 5 = low E, matches soloin-fretboard's convention
  fretOffset: number; // relative to cagedBoxRange(shape, key.root).start — transposes to any key for free
  beat: number; // start beat within the riff, 0-based
  duration: number; // length in beats
  // How this note is reached from the previous one (always on the same string).
  technique?: 'slide' | 'hammer' | 'pull';
  bend?: number; // semitones the note is bent up after picking: 1 = half, 2 = full
}

export interface Riff {
  id: string;
  name: LocalizedText;
  scale: ScaleName;
  shape: CagedShape;
  totalBeats: number;
  notes: RiffNote[];
}

